#include <array>
#include <charconv>
#include <format>
#include <iostream>
#include <optional>
#include <print>
#include <string>
#include <string_view>

struct Date {
    int day;
    int month;
};

std::optional<int> parse_int(std::string_view text) {
    int value = 0;
    auto [end, error] = std::from_chars(text.data(), text.data() + text.size(), value);
    if (text.empty() || error != std::errc{} || end != text.data() + text.size()) {
        return std::nullopt;
    }
    return value;
}

std::optional<Date> parse_date(std::string_view text) {
    std::size_t dot = text.find('.');
    if (dot == std::string_view::npos) {
        return std::nullopt;
    }
    std::optional<int> day = parse_int(text.substr(0, dot));
    std::optional<int> month = parse_int(text.substr(dot + 1));
    if (!day || !month) {
        return std::nullopt;
    }
    return Date{*day, *month};
}

std::optional<Date> validate(Date d) {
    constexpr std::array<int, 12> days = {31, 28, 31, 30, 31, 30, 31, 31, 30, 31, 30, 31};
    if (d.month < 1 || d.month > 12) {
        return std::nullopt;
    }
    if (d.day < 1 || d.day > days[static_cast<std::size_t>(d.month - 1)]) {
        return std::nullopt;
    }
    return d;
}

int main() {
    constexpr std::array<std::string_view, 12> names = {
        "января", "февраля", "марта", "апреля", "мая", "июня",
        "июля", "августа", "сентября", "октября", "ноября", "декабря"};
    std::string line;
    while (std::getline(std::cin, line)) {
        std::string text = parse_date(line)
                               .and_then(validate)
                               .transform([&names](Date d) {
                                   return std::format("{} {}", d.day, names[static_cast<std::size_t>(d.month - 1)]);
                               })
                               .value_or("неверная дата");
        std::println("{}", text);
    }
    return 0;
}

