#include <optional>
#include <print>

std::optional<int> half(int x) {
    if (x % 2 != 0) {
        return std::nullopt;
    }
    return x / 2;
}

int main() {
    std::println("{} {}", half(20).and_then(half).value_or(-1), half(6).and_then(half).value_or(-1));
    return 0;
}

